function OrganizationDesk({userId,isOwner,context}:{userId:string;isOwner:boolean;context:unknown}) {
  const list=useListOrganizations();const [selected,setSelected]=useState("");
  const orgs=list.data?.items??[];const selectedOrg=orgs.find(org=>org.id===selected)??orgs[0];
  const raw=field(context,"organizationId")??field(context,"organization_id");const rawIds=field(context,"organizationIds");
  const ids=Array.isArray(rawIds)?rawIds.filter((id):id is string=>typeof id==="string"):typeof raw==="string"?[raw]:null;
  const visible=isOwner?orgs:ids?orgs.filter(org=>ids.includes(org.id)):orgs;
  useEffect(()=>{if(selectedOrg&&selected!==selectedOrg.id)setSelected(selectedOrg.id)},[selectedOrg?.id,selected]);
  if(list.isLoading)return <div className="loading-panel"><span className="skeleton skeleton-title"/><span className="skeleton skeleton-line"/><span className="skeleton skeleton-line short"/></div>;
  if(list.isError)return <StatePanel kind="error" title="تعذر تحميل الجهات">{errorText(list.error)} <button className="button button-outline" onClick={()=>void list.refetch()}>إعادة المحاولة</button></StatePanel>;
  return <div className="desk"><div className="desk-toolbar"><div><span className="section-kicker">الجهات والصلاحيات</span><h2>{isOwner?"إدارة الجهات":"جهاتك المصرّح بها"}</h2></div></div>
    {visible.length===0?<StatePanel title={isOwner?"لم تُضف جهات بعد":"لا توجد جهات متاحة"}>{isOwner?"لم تُضف جهات إلى المنصة بعد.":"لا تظهر إلا الجهات التي مُنح حسابك صلاحية الوصول إليها."}</StatePanel>:<>
      <div className="org-strip" role="list" aria-label="الجهات">{visible.map(org=><div className="org-workspace-item" key={org.id}><button aria-current={selectedOrg?.id===org.id?"true":undefined} className={`org-tab ${selectedOrg?.id===org.id?"active":""}`} onClick={()=>setSelected(org.id)}><span className="org-tab-icon"><Building2 size={18}/></span><span><b>{org.name}</b><small>{kindName[org.kind]}</small></span><StatusPill status={org.status}/></button><Link className="org-detail-link" href={`/workspace/organizations/${org.id}`}>إدارة تفاصيل الجهة <ArrowLeft size={14}/></Link></div>)}</div>
      {selectedOrg&&<OrganizationDetail key={selectedOrg.id} org={selectedOrg} userId={userId} isOwner={isOwner}/>}
    </>}
  </div>;
}
