  const cache=useQueryClient();const branchQ=useListBranches(org.id,{query:{queryKey:getListBranchesQueryKey(org.id),enabled:!!org.id,refetchOnMount:"always"}});
  const membersQ=useListMemberships(org.id,{query:{queryKey:getListMembershipsQueryKey(org.id),enabled:!!org.id,refetchOnMount:"always"}});
  const members=membersQ.data?.items??[];const self=members.find(member=>member.user_id===userId&&member.active);
  const allowedBranchIds=self?.scope==="branches"?self.branchIds:null;
